INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (1,'ASH-001','המגדלור בגבעת יונה','כביש 4 אדר׳ חיה','רובע א׳','2077/2',false,31.8136,34.6474,NULL,false,NULL,false,'מגדל ניווט',ARRAY['תקופה ישראלית']::text[],'א',NULL,NULL,NULL,'היסטורית, אדריכלית','ממ"י / עיריית אשדוד','קיים - סגור לציבור',NULL,'מגדל ניווט',ARRAY['היסטורית','אדריכלית']::text[],'גבוהה','בנוי בראשית תקופת הנמל. גובה 138 מטר, מגדל הניווט הגבוה בישראל. ניווט ספינות בדפוס שלושה הבזקים כל 20 שניות. סגור לציבור משנת 2009, משמש כיום כמאגר מים.','נמצא בגבעת יונה — הגבעה הגבוהה ביותר באשדוד (53 מ׳ מעל פני הים). תוכנן לשרת את נמל אשדוד בראשית שנות ה-60. הזכוכית הדיאופטרית הגיעה מהמגדלור הישן בתל אביב.',NULL,'{}'::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (2,'ASH-002','גשר עד הלום / הפילבוקס / עמדת ויקרס','פארק עד הלום','נחל לכיש','182/33, 182/49-51',false,31.8012,34.6613,NULL,false,NULL,false,'גשר היסטורי',ARRAY['תקופה ישראלית','תקופה מנדטורית']::text[],'א',NULL,NULL,NULL,'לאומית, היסטורית','ממ"י / עיריית אשדוד','קיים - פארק לאומי',NULL,'גשר היסטורי',ARRAY['לאומית','היסטורית']::text[],'גבוהה','גשר אבן ממאה ה-13 (תקופה ממלוכית) על יסודות רומיים, חוצה את נחל לכיש. פוצץ ב-12.5.1948 על ידי גדוד גבעתי לעצור את ההתקדמות המצרית — "עד הלום ולא תוסיף". הפילבוקס — מצדית בטון בריטית (1936). עמדת ויקרס — עמדת צה"ל משנות ה-50.','אתר הנצחה לאומי. כאן נעצרה ההתקדמות המצרית במלחמת העצמאות. הגשר הוכרז כאתר מורשת. הפארק מנוהל על ידי עיריית אשדוד.',NULL,ARRAY['https://en.wikipedia.org/wiki/Ad_Halom']::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (3,'ASH-003','אובליסק מיצרי','פארק עד הלום','נחל לכיש','182/33',false,31.8014,34.661,1990,true,NULL,false,'אנדרטה',ARRAY['תקופה ישראלית']::text[],'ב',NULL,NULL,NULL,'לאומית, היסטורית','עיריית אשדוד','קיים',NULL,'אנדרטה',ARRAY['לאומית','היסטורית']::text[],'בינונית','אנדרטה הוקמה בשנת 1990 לאחר הסכם השלום ישראל-מצרים (1979), לזכר חיילים מצרים שנפלו בקרב עד הלום. כתובות בערבית, אנגלית, עברית והירוגליפים. אחד מסמלי הפיוס ישראלי-מצרי.','הוקם ביוזמת שני הצדדים לאחר הסכם השלום. מהווה ביטוי חריג לפיוס ישראלי-ערבי. הכתובת ההירוגליפית מוסיפה ממד היסטורי עתיק.',NULL,'{}'::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (4,'ASH-004','הקליפורניות (בנק הפועלים + בנק לאומי)','רח׳ הורדים 7 ו-3','רובע א׳','2061/161',false,31.8084,34.6465,NULL,false,NULL,false,'בנק / מסחר',ARRAY['תקופה ישראלית']::text[],'ב',NULL,NULL,NULL,'היסטורית','ממ"י','קיים',NULL,'בנק / מסחר',ARRAY['היסטורית']::text[],'בינונית','בנק הפועלים הראשון ובנק לאומי הראשון באשדוד. בנויות בראשית שנות ה-60 כמבנים חד-קומתיים ראשונים בעיר. כינויין "הקליפורניות" בשל חיפוי הלוחות המיוחד. מייצגות את ראשית הפעילות הכלכלית בעיר הצעירה.','מהמבנים הציבוריים הראשונים שנבנו באשדוד. עדות לפעילות הבנקאית שהחלה בד בבד עם הקמת הנמל. הסגנון מהווה דוגמה לאדריכלות תנועה מודרנית ישראלית של שנות ה-60.',NULL,'{}'::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (5,'ASH-005','בית קנדה — מרכז קליטה','רח׳ רוגוזין / שבי ציון','רובע א׳','2061/111',false,31.8035,34.6421,NULL,false,'משה לופנפלד',true,'מרכז קליטה',ARRAY['תקופה ישראלית']::text[],'א',NULL,NULL,NULL,'אדריכלית, היסטורית','הסוכנות היהודית','פעיל - שופץ',NULL,'מרכז קליטה',ARRAY['אדריכלית','היסטורית']::text[],'גבוהה','מרכז קליטה תוכנן על ידי האדריכל משה לופנפלד. בטון חשוף בסגנון ברוטליסטי. 2 חצרות פנימיות גדולות לאוורור. דירות זעירות (15 מ"ר) לקליטת עולים חדשים. ממן על ידי הממשלה הקנדית. שופץ בשנים אחרונות ועדיין פעיל.','ממן על ידי הממשלה הקנדית כסיוע לישראל בקליטת עלייה. אחד ממרכזי הקליטה הראשונים שהוקמו באשדוד. מהווה עדות לגל העלייה הגדול של שנות ה-50-60.',NULL,'{}'::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (6,'ASH-006','בית הכנסת הקראי — ענן הנשיא','רח׳ האצל 7','רובע א׳','2061/64',false,31.8106,34.6449,NULL,false,NULL,false,'בית כנסת',ARRAY['תקופה ישראלית']::text[],'א',NULL,NULL,NULL,'היסטורית, תרבותית','עיריית אשדוד','קיים - פעיל',NULL,'בית כנסת',ARRAY['היסטורית','תרבותית']::text[],'גבוהה','בית הכנסת הקראי הגדול בישראל, ממוקם באשדוד — הריכוז הגדול ביותר של קהילה קראית בישראל (מעל 3,000 משפחות). נקרא על שם ענן בן דוד (700-800 לסה"נ), מייסד הכת הקראית. תפילה פעמיים ביום, שמירה על מסורת נפרדת מהרבנות.','הקראים הם עדה יהודית שאינה מקבלת את סמכות התלמוד. רוב הקראים בישראל עלו ממצרים בשנות ה-50. אשדוד היא מרכז הפעילות הקראית הגדול בישראל. בית הכנסת מהווה ציר תרבותי-דתי מרכזי.',NULL,ARRAY['https://www.heritage-center.org.il/']::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (7,'ASH-007','מרכז רובעי א׳','רח׳ רוגוזין / שבי ציון','רובע א׳','2077/129-157',false,31.8038,34.6425,NULL,false,NULL,false,'מרכז מסחרי',ARRAY['תקופה ישראלית']::text[],'א',NULL,NULL,NULL,'אדריכלית, היסטורית','פרטיים','קיים',NULL,'מרכז מסחרי',ARRAY['אדריכלית','היסטורית']::text[],'גבוהה','הלב הפועם של רובע א׳ — שכונת האם של אשדוד. משמר את עיקרון התכנון המקורי של העיר: קומת קרקע מסחרית עם קולונדה (עמודים), משרדים בשתי קומות על עמודים, בריכת מים ציבורית. תכנן על פי עקרונות CIAM של האדריכל שרון בתקופת הקמת העיר.','רובע א׳ נוסד בשנות ה-50 כשכונת אם של אשדוד. המרכז הרובעי תוכנן לשמש קהילה שלמה. הקולונדה והעמודים מאפיינים את האדריכלות הציבורית הישראלית של אותה תקופה.',NULL,'{}'::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (8,'ASH-008','הגן האדום','רח׳ חיבת ציון 8','רובע א׳','2077/161',false,31.8102,34.6463,NULL,false,NULL,false,'גן ילדים',ARRAY['תקופה ישראלית']::text[],'ב',NULL,NULL,NULL,'היסטורית','עיריית אשדוד','קיים',NULL,'גן ילדים',ARRAY['היסטורית']::text[],'בינונית','גן הילדים הראשון של אשדוד, בנוי בראשית שנות ה-60 וצבוע אדום — הצבע שהקנה לו את שמו. הגננת הראשונה: רחל לנגסנר. עוזרות: ז׳וליאט אניג׳ר ואסתר ג׳נח. מסמל את ראשית חיי הקהילה בעיר הצעירה.','מהמוסדות הציבוריים הראשונים שנפתחו ברובע א׳. צבעו האדום הבולט הפך לסמל עבור הדור הראשון של ילדי אשדוד. שימש גן ילדים פעיל עד לשנים האחרונות.',NULL,'{}'::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (9,'ASH-009','לשכת עבודה','רח׳ הראשונים 7','רובע א׳','2086/78',false,31.81,34.6475,NULL,false,NULL,false,'משרד ציבורי',ARRAY['תקופה ישראלית']::text[],'ב',NULL,NULL,NULL,'היסטורית','ר"מי / פרטיים','קיים',NULL,'משרד ציבורי',ARRAY['היסטורית']::text[],'בינונית','בנוי בראשית שנות ה-60 ושימש כלשכת עבודה לבוגרים ולנוער. עדות לפעילות ההסתדרות ומשרד העבודה בעיר הצעירה. בשנת 1966 טיפל במשבר תעסוקה חמור (1,700 פועלים). כיום: חכירה כמשרד פרטי.','שנת 1966 — תקופת מיתון חמורה באשדוד. הלשכה טיפלה בגל פיטורים של 1,700 פועלים. מהווה עדות לעיר של פועלים ונמל.',NULL,'{}'::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (10,'ASH-010','בית מלון ראשון','רח׳ הראשונים 43','רובע א׳','2085/22',false,31.8049,34.6446,NULL,false,NULL,false,'בית מלון',ARRAY['תקופה ישראלית']::text[],'ב',NULL,NULL,NULL,'היסטורית','פרטיים','קיים',NULL,'בית מלון',ARRAY['היסטורית']::text[],'בינונית','בנוי בראשית שנות ה-60, מבנה "שכון" בן 3 קומות ששימש כבית המלון הראשון באשדוד. שימש לאחר מכן כמשרד קצין העיר הצבאי. עדות לצמיחה המהירה של העיר שהצריכה תשתית אירוח מוקדמת.','מיאמי הוטל הוא בית המלון הוותיק ביותר הפעיל באשדוד. מבנה זה קדם לו ושימש מבקרים ופקידים בתקופת הקמת הנמל.',NULL,'{}'::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (11,'ASH-011','פארק נחל לכיש','נחל לכיש','נחל לכיש',NULL,false,31.8166,34.6494,1996,true,NULL,false,'פארק',ARRAY['תקופה ישראלית']::text[],'א',NULL,NULL,NULL,'נופית, אקולוגית','ממ"י / חנ"י','קיים - פתוח לציבור',NULL,'פארק',ARRAY['נופית','אקולוגית']::text[],'גבוהה','פארק של 650 דונם הוקם בשנת 1996 לאורך הגדה הדרומית של נחל לכיש. כולל שבילי הליכה ואופניים, בעלי חיים (אנטילופות, זברות, אילות, יענים). כניסה חופשית. מהווה מסדרון אקולוגי חיוני לנחלת הלכיש.','חלק מפרויקט שיקום נחל לכיש הארצי. מנוהל על ידי עיריית אשדוד וחברת נופי הארץ. מהווה ריאות ירוקות לתושבי העיר.',NULL,ARRAY['https://visit.ashdod.muni.il/en/night-life/lachish-park/']::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (12,'ASH-012','שדרת השקמים','דרום (שד׳ השקמים)','דרום',NULL,false,31.785,34.635,NULL,false,NULL,false,'גנון / שדרה',ARRAY['תקופה ישראלית','תקופות קדומות']::text[],'ב',NULL,NULL,NULL,'אקולוגית, נופית','ממ"י / עיריית אשדוד','קיים',NULL,'גנון / שדרה',ARRAY['אקולוגית','נופית']::text[],'בינונית','שדרה היסטורית של עצי שקמה עתיקים (Ficus sycomorus) בדרום אשדוד. עצי שקמה הם עצים מקראיים — מוזכרים בתנ"ך כעצי השפלה. מייצגים שכבה ביולוגית היסטורית של אזור אשדוד. שמירה על מערכת אקולוגית ייחודית.','עץ השקמה (שקמה מקראית / Ficus sycomorus) הוא עץ מסורתי ארץ-ישראלי המוזכר במקרא. מהווה בית גידול לעופות ושמירה על מגוון ביולוגי.',NULL,'{}'::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (13,'ASH-013','תל מור','דרום אשדוד — פי הנחל','דרום',NULL,false,31.7686,34.6317,NULL,false,NULL,false,'תל ארכאולוגי',ARRAY['תקופות קדומות','תקופת הברונזה','תקופת הברזל','תקופה פרסית-הלניסטית']::text[],'א',NULL,NULL,NULL,'ארכאולוגית','קרקע ציבורית','קיים',NULL,'תל ארכאולוגי',ARRAY['ארכאולוגית']::text[],'גבוהה','תל ארכאולוגי עתיר ממצאים בפי נחל לכיש, ליד נמל אשדוד. מקובץ יישוב מהתקופה הפלשתית, רומית ופרסית. חפירות גילו מבצר מהברונזה המאוחרת (כ-1400 לפנה"ס), בתים, מבנים ציבוריים, מערכות מים, כלי חרס, תכשיטים ונשק.','חפירה בשנת 1986 בניהול י. אלדר, רשות העתיקות. מספר אתר IAA: A-1433. תל מור שלט על כניסת הספינות לפי הנחל בתקופות קדומות.','A-1433/1986',ARRAY['https://www.biblewalks.com/telmor/']::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_buildings (site_no,city_registry_id,name,address,neighborhood,parcel,is_complex,lat,lng,year_built,year_built_verified,architect,architect_verified,style,historical_periods,protection_level,floors,total_built_area,construction_type,documentation_reason,owner,current_use,original_use,building_type,preservation_reasons,priority_level,full_description,additional_info,iaa_reference,gov_sources,status) VALUES (14,'ASH-014','מצודת אשדוד ים','חוף הים — אשדוד ים','חוף',NULL,false,31.7803,34.6217,NULL,false,NULL,false,'מצודה ארכאולוגית',ARRAY['תקופות קדומות','תקופה ביזנטית','תקופה אסלאמית קדומה']::text[],'א',NULL,NULL,NULL,'ארכאולוגית, נופית','ממ"י','קיים - טיילת חוף',NULL,'מצודה ארכאולוגית',ARRAY['ארכאולוגית','נופית']::text[],'גבוהה','מצודה חופית רב-תקופתית — מהברונזה המאוחרת ועד התקופה האסלאמית הקדומה. מבצר אסלאמי קדום (40x60 מ׳) — מזוהה עם ה"ריבאט" שנזכר אצל אל-מוקדסי (המאה ה-10). חפירות IAA בשנים 1997-1999. כולל מתחם כנסיה ביזנטית ושרידים הלניסטיים.','שמורה בתב"ע 122/101/02/3. הריבאט האסלאמי הוא מבנה ביצור דתי ששימש לשמירה על החוף. האתר נחפר לאחר שנחשף בסיפוח לשטח הבנייה של אשדוד.','חפירות IAA 1997-1999',ARRAY['https://archaeological.wixsite.com/ashdodyam/copy-of-introducing-ashdod-yam']::text[],'לא_התחיל') ON CONFLICT (site_no) DO UPDATE SET city_registry_id=EXCLUDED.city_registry_id,name=EXCLUDED.name,address=EXCLUDED.address,neighborhood=EXCLUDED.neighborhood,parcel=EXCLUDED.parcel,is_complex=EXCLUDED.is_complex,lat=EXCLUDED.lat,lng=EXCLUDED.lng,year_built=EXCLUDED.year_built,year_built_verified=EXCLUDED.year_built_verified,architect=EXCLUDED.architect,architect_verified=EXCLUDED.architect_verified,style=EXCLUDED.style,historical_periods=EXCLUDED.historical_periods,protection_level=EXCLUDED.protection_level,floors=EXCLUDED.floors,total_built_area=EXCLUDED.total_built_area,construction_type=EXCLUDED.construction_type,documentation_reason=EXCLUDED.documentation_reason,owner=EXCLUDED.owner,current_use=EXCLUDED.current_use,original_use=EXCLUDED.original_use,building_type=EXCLUDED.building_type,preservation_reasons=EXCLUDED.preservation_reasons,priority_level=EXCLUDED.priority_level,full_description=EXCLUDED.full_description,additional_info=EXCLUDED.additional_info,iaa_reference=EXCLUDED.iaa_reference,gov_sources=EXCLUDED.gov_sources,status=EXCLUDED.status;
INSERT INTO shimur_routes (slug,title,description,theme,is_public) VALUES ('route-1','שנות ה-60: העיר מתעצבת','מסלול בין המבנים הציבוריים הראשונים שהוקמו באשדוד — מלשכת העבודה דרך הקליפורניות ועד בית קנדה. סיפור של עיר צעירה שצומחת.','תקופה',true) ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title,description=EXCLUDED.description,theme=EXCLUDED.theme;
INSERT INTO shimur_route_sites (route_id,building_id,position,narrative_text) VALUES ((SELECT id FROM shimur_routes WHERE slug='route-1'),(SELECT id FROM shimur_buildings WHERE site_no=9),1,'לשכת העבודה — המפגש הראשון של עולים חדשים עם מקום עבודה בעיר הצעירה.');
INSERT INTO shimur_route_sites (route_id,building_id,position,narrative_text) VALUES ((SELECT id FROM shimur_routes WHERE slug='route-1'),(SELECT id FROM shimur_buildings WHERE site_no=10),2,'בית המלון הראשון שירת פקידים ומבקרים בתקופת הקמת הנמל.');
INSERT INTO shimur_route_sites (route_id,building_id,position,narrative_text) VALUES ((SELECT id FROM shimur_routes WHERE slug='route-1'),(SELECT id FROM shimur_buildings WHERE site_no=4),3,'הקליפורניות — הבנקים הראשונים. תחילת הפעילות הכלכלית.');
INSERT INTO shimur_route_sites (route_id,building_id,position,narrative_text) VALUES ((SELECT id FROM shimur_routes WHERE slug='route-1'),(SELECT id FROM shimur_buildings WHERE site_no=5),4,'בית קנדה — מרכז קליטה ברוטליסטי. כאן התחילו חייהם של אלפי עולים.');
INSERT INTO shimur_route_sites (route_id,building_id,position,narrative_text) VALUES ((SELECT id FROM shimur_routes WHERE slug='route-1'),(SELECT id FROM shimur_buildings WHERE site_no=8),5,'הגן האדום — גן הילדים הראשון. כאן גדל הדור הראשון של ילדי אשדוד.');
INSERT INTO shimur_routes (slug,title,description,theme,is_public) VALUES ('route-2','מהעת העתיקה ועד היום','מסלול ארכאולוגי — מתל מור דרך מצודת אשדוד ים ועד גשר עד הלום. אלפי שנים של היסטוריה על קו החוף.','ארכאולוגיה',true) ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title,description=EXCLUDED.description,theme=EXCLUDED.theme;
INSERT INTO shimur_route_sites (route_id,building_id,position,narrative_text) VALUES ((SELECT id FROM shimur_routes WHERE slug='route-2'),(SELECT id FROM shimur_buildings WHERE site_no=13),1,'תל מור — יישוב עתיק בפי הנחל. מבצר מהברונזה המאוחרת שלט על כניסת הספינות.');
INSERT INTO shimur_route_sites (route_id,building_id,position,narrative_text) VALUES ((SELECT id FROM shimur_routes WHERE slug='route-2'),(SELECT id FROM shimur_buildings WHERE site_no=14),2,'מצודת אשדוד ים — ריבאט אסלאמי וכנסיה ביזנטית. שכבות של תרבויות על חוף הים.');
