INSERT INTO shimur_routes (slug,title,description,theme,is_public) VALUES ('route-3','רובע א׳ — שכונת האם','סיור ברובע א׳ — השכונה הראשונה של אשדוד. מהמרכז הרובעי דרך בית הכנסת הקראי ועד הגן האדום.','שכונה',true) ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title,description=EXCLUDED.description,theme=EXCLUDED.theme;
INSERT INTO shimur_route_sites (route_id,building_id,position,narrative_text) VALUES ((SELECT id FROM shimur_routes WHERE slug='route-3'),(SELECT id FROM shimur_buildings WHERE site_no=7),1,'המרכז הרובעי — הלב הפועם. קולונדה, עמודים, בריכת מים ציבורית. תכנון על פי עקרונות CIAM.');
