INSERT INTO shimur_route_sites (route_id,building_id,position,narrative_text) VALUES ((SELECT id FROM shimur_routes WHERE slug='route-3'),(SELECT id FROM shimur_buildings WHERE site_no=6),3,'בית הכנסת הקראי — מרכז הקהילה הקראית הגדולה בישראל. מסורת ייחודית.');
