INSERT INTO shimur_routes (slug,title,description,theme,is_public) VALUES ('route-4','טבע ונוף — המסדרון הירוק','מסלול טבע — מפארק נחל לכיש דרך שדרת השקמים ועד המגדלור בגבעת יונה. טבע, אקולוגיה ונוף.','טבע',true) ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title,description=EXCLUDED.description,theme=EXCLUDED.theme;
