INSERT INTO shimur_route_sites (route_id,building_id,position,narrative_text) VALUES ((SELECT id FROM shimur_routes WHERE slug='route-4'),(SELECT id FROM shimur_buildings WHERE site_no=1),3,'המגדלור בגבעת יונה — 138 מטר. הנקודה הגבוהה ביותר באשדוד. שלושה הבזקים כל 20 שניות.');
